import sys, json, uuid, datetime

# The episodes of a conversation, read whole and in order (empathy plan C4,
# agent-2 A4). Two doors share this one read:
#
#   `in_query` with `memory_tier: "session"` -- the episodes of ONE session,
#   for the round that asks (`context.audience_now`, `context.channel`), as a
#   `bundle`. Recall's tier-0 leg reads `session_id` too, but as a token
#   budgeted mix of beliefs, preview and at most a dozen episodes without ids
#   (memory-hive README, tier 0); an evaluation of a conversation and a check
#   of a quote need every turn, in order, with the id it can cite.
#
#   `in_conversations` -- the same read for a READER outside the round (a
#   counselor, an evaluation): `{reader, audience_set, session_id? |
#   channel? + since?, max_chars?}` in the body, the answer on
#   `conversations`. Only sessions on conversation channels leave this door
#   (`conversation_channels`): a role run, an ask or an inner turn is not a
#   conversation, and a reader that evaluated those would evaluate itself.
#
# No model call. The round is fail-closed: no round, no answer; a row
# recorded without participants is read by nobody; a row the member asked to
# forget or muted stays in the store and leaves no transcript (counted as
# `withheld`, never shown). The answer is bounded by `max_chars` of the ask
# (default `session_max_chars`) and says `truncated` when it was cut.

doc = json.load(sys.stdin)
P = doc.get("params") or {}
d = doc.get("body") or {}
envelope = doc.get("envelope") or {}
h = envelope.get("header") or {}
ctx = h.get("context") or {}
hop = h.get("hop") or {}
op = hop.get("operation")
err = str(hop.get("error_code", "") or "")

MAX_CHARS = int(P.get("session_max_chars", 24000))
PAGE = int(P.get("session_page", 2000))
CHANNELS = P.get("conversation_channels")
if not isinstance(CHANNELS, dict):
    CHANNELS = {"include": ["*"], "exclude": ["role", "ask", "inner"]}
FORGET_SOURCE = "forget_request:"
ROLES = {"user": "person", "assistant": "assistant", "peer": "peer"}


def emit(msgs):
    sys.stdout.write(json.dumps(msgs))
    sys.exit(0)


def round_of(raw):
    """A participant set: a JSON list (or its text). None when it is absent,
    unreadable or empty -- an empty round is no round (fail-closed)."""
    if raw is None:
        return None
    items = raw
    if not isinstance(raw, list):
        text = str(raw).strip()
        if not text:
            return None
        try:
            items = json.loads(text)
        except Exception:
            return None
    if not isinstance(items, list):
        return None
    got = {str(i) for i in items if str(i).strip()}
    return got or None


def visible(row, rnd, channel="", open_history=False):
    """The read rule of every reader of this hive (README, audience gate):
    `*` is universal, otherwise the round must be a subset of the row's round;
    the open-history clause never crosses a channel."""
    aud = round_of(row.get("audience_set"))
    if not aud or rnd is None:
        return False
    if "*" in aud or rnd <= aud:
        return True
    return bool(open_history and channel and str(row.get("channel") or "") == channel)


def withheld(row):
    if str(row.get("closure_source") or "").startswith(FORGET_SOURCE):
        return True
    return bool(str(row.get("muted_at") or "").strip()) and not str(row.get("unmuted_at") or "").strip()


def is_conversation(channel):
    """A channel's class is the part before its first `:` (`inner:care` is
    `inner`); a row without a channel is no conversation."""
    cls = str(channel or "").split(":", 1)[0]
    if not cls:
        return False
    if cls in [str(x) for x in CHANNELS.get("exclude") or []]:
        return False
    inc = [str(x) for x in CHANNELS.get("include") or []]
    return "*" in inc or cls in inc


def cap_of(raw):
    if raw is None or raw == "":
        return MAX_CHARS
    try:
        n = int(raw)
    except Exception:
        return None
    return n if n >= 1 else None


def is_time(text):
    try:
        datetime.datetime.fromisoformat(str(text).replace("Z", "+00:00"))
        return True
    except Exception:
        return False


def read_op(where):
    return {"operation": "select", "table": "episodes",
            "columns": ["id", "session_id", "sender", "speaker", "speaker_name", "channel",
                        "audience_set", "content", "happened_at", "recorded_at",
                        "closure_source", "muted_at", "unmuted_at"],
            "where": where,
            "order_by": [{"col": "happened_at", "dir": "asc"},
                         {"col": "recorded_at", "dir": "asc"},
                         {"col": "id", "dir": "asc"}],
            "limit": PAGE + 1}


def ask_store(req, where):
    emit([{"header": {"route": "sstore", "phase": "sessions",
                      "conv_req": json.dumps(req, sort_keys=True)},
           "messages": [{"origin": "assistant", "type": "tool_call", "id": "s-read",
                         "text": json.dumps(read_op(where))}]}])


def refuse(req, code, detail=""):
    if req.get("form") == "conversations":
        emit([{"header": {"route": "conversations", "reader": req.get("reader", ""),
                          "error_code": code},
               "messages": [{"origin": "tool", "type": "tool_result", "id": "conversations",
                             "text": json.dumps({"reader": req.get("reader", ""),
                                                 "error_code": code, "detail": detail})}]}])
    emit([{"header": {"route": "reject", "phase": "request", "recall_id": req.get("rid", ""),
                      "reject_reason": code},
           "messages": [{"origin": "tool", "type": "tool_result", "id": "r-reject",
                         "text": "recall rejected: %s%s" % (code, detail)}]}])


def episodes_of(rows, req):
    """(kept rows, withheld count): the rows this ask may see, in the store's
    order, each checked again here."""
    rnd = round_of(req.get("round"))
    kept, held = [], 0
    for row in rows:
        if not isinstance(row, dict):
            continue
        if req["form"] == "conversations" and not is_conversation(row.get("channel")):
            continue
        if not visible(row, rnd, req.get("channel_now", ""), req.get("open_history", False)):
            continue
        if withheld(row):
            held += 1
            continue
        kept.append(row)
    return kept, held


def entry(row):
    e = {"episode_ref": str(row.get("id") or ""),
         "role": ROLES.get(str(row.get("sender") or ""), str(row.get("sender") or "")),
         "text": str(row.get("content") or ""),
         "happened_at": str(row.get("happened_at") or "")}
    if str(row.get("speaker") or ""):
        e["speaker"] = str(row["speaker"])
    if str(row.get("speaker_name") or ""):
        e["speaker_name"] = str(row["speaker_name"])
    return e


def cut(rows, cap, page_full):
    """Whole episodes in order until `cap` characters of text; an episode that
    does not fit even first is cut to the cap and marked. Never silent."""
    out, used, truncated = [], 0, page_full
    for row in rows:
        e = entry(row)
        n = len(e["text"])
        if used + n > cap:
            truncated = True
            if not out:
                e["text"] = e["text"][:cap]
                e["cut"] = True
                out.append(e)
            break
        out.append(e)
        used += n
    return out, truncated


# ---------------------------------------------------------------- store reply
if str(ctx.get("mem_phase", "")) == "sessions" and op is not None:
    try:
        req = json.loads(str(ctx.get("conv_req") or ""))
    except Exception:
        req = None
    if not isinstance(req, dict) or req.get("form") not in ("session", "conversations"):
        sys.stderr.write("sessions: a store reply arrived without its ask, dropped\n")
        emit([])
    if err:
        refuse(req, "store_refused", " (%s)" % err)
    try:
        rows = json.loads((d.get("messages") or [{}])[0].get("text", "") or "[]")
    except Exception:
        rows = []
    if not isinstance(rows, list):
        rows = []
    page_full = len(rows) > PAGE
    rows = rows[:PAGE]
    kept, held = episodes_of(rows, req)
    cap = int(req.get("max_chars") or MAX_CHARS)
    if req["form"] == "session":
        eps, truncated = cut(kept, cap, page_full)
        bundle = {"tier": "session", "session_id": req.get("session_id", ""),
                  "episodes": eps, "truncated": truncated, "withheld": held}
        lines = ["%s: %s" % (e.get("speaker_name") or e["role"], e["text"]) for e in eps]
        header = {"route": "bundle", "recall_id": req.get("rid", "")}
        if not eps:
            header["recall_empty"] = "1"
        emit([{"header": header,
               "system": {"memory": {"bundle": {"text": json.dumps(bundle, sort_keys=True)}}},
               "messages": [{"origin": "tool", "type": "tool_result", "id": "recall",
                             "text": "\n".join(lines) if lines else
                             "This memory holds no turn of this session for this round."}]}])
    sessions, order = {}, []
    for row in kept:
        sid = str(row.get("session_id") or "")
        if sid not in sessions:
            sessions[sid] = []
            order.append(sid)
        sessions[sid].append(row)
    left, truncated, out = cap, page_full, []
    for sid in order:
        if left <= 0:
            truncated = True
            break
        eps, cut_here = cut(sessions[sid], left, False)
        if eps:
            out.append({"session_id": sid, "channel": str(sessions[sid][0].get("channel") or ""),
                        "episodes": eps})
        left -= sum(len(e["text"]) for e in eps)
        if cut_here:
            truncated = True
            break
    answer = {"reader": req.get("reader", ""), "sessions": out, "truncated": truncated,
              "withheld": held}
    emit([{"header": {"route": "conversations", "reader": req.get("reader", "")},
           "messages": [{"origin": "tool", "type": "tool_result", "id": "conversations",
                         "text": json.dumps(answer, sort_keys=True)}]}])

if op is not None:
    emit([])

# ---------------------------------------------------------------- requests
route = str(hop.get("route", ""))
if route == "in_query":
    req = {"form": "session", "rid": str(uuid.uuid4())}
    if round_of(ctx.get("audience_now")) is None:
        refuse(req, "missing_audience")
    channel = str(ctx.get("channel") or "").strip()
    if not channel:
        refuse(req, "missing_channel")
    cap = cap_of(hop.get("max_chars"))
    if cap is None:
        refuse(req, "invalid_input", " (max_chars: a whole number >= 1)")
    sid = str(ctx.get("session_id") or "default")
    req.update({"round": sorted(round_of(ctx.get("audience_now"))), "channel_now": channel,
                "open_history": str(ctx.get("channel_open_history", "0")).strip().lower()
                in ("1", "true", "yes", "on"),
                "session_id": sid, "max_chars": cap})
    ask_store(req, {"session_id": sid})

if route == "in_conversations":
    reader = str(d.get("reader") or "")
    req = {"form": "conversations", "reader": reader}
    rnd = round_of(d.get("audience_set"))
    if rnd is None:
        refuse(req, "missing_audience")
    cap = cap_of(d.get("max_chars"))
    if cap is None:
        refuse(req, "invalid_input", " (max_chars: a whole number >= 1)")
    sid = str(d.get("session_id") or "").strip()
    channel = str(d.get("channel") or "").strip()
    since = str(d.get("since") or "").strip()
    if sid and (channel or since):
        refuse(req, "invalid_input", " (session_id, or channel and/or since -- not both)")
    if not (sid or channel or since):
        refuse(req, "invalid_input", " (session_id, channel or since)")
    if since and not is_time(since):
        refuse(req, "invalid_input", " (since: an ISO 8601 time)")
    where = {}
    if sid:
        where["session_id"] = sid
    if channel:
        where["channel"] = channel
    if since:
        where["happened_at"] = {"gte": since}
    req.update({"round": sorted(rnd), "max_chars": cap})
    ask_store(req, where)

emit([])
